"""Report-backed service tables. Prices and workloads live in the downloadable JSON."""
from html import escape
from pathlib import Path
import json

ROOT = Path(__file__).resolve().parents[1]
DATA = json.loads((ROOT/'dist/downloads/service-budget.json').read_text())

def table(caption, headers, rows):
    return '<div class="budget-table" tabindex="0" role="region" aria-label="'+escape(caption)+'"><table><caption>'+caption+'</caption><thead><tr>'+''.join('<th scope="col">'+h+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(('<th scope="row">' if i==0 else '<td>')+str(v)+('</th>' if i==0 else '</td>') for i,v in enumerate(row))+'</tr>' for row in rows)+'</tbody></table></div>'

def service_page():
    d=DATA
    prices=table('Table 1. Report price snapshot · USD per million tokens', ['Model','Input','Output'],[(m['name'],f"${m['input_per_million']:.2f}",f"${m['output_per_million']:.2f}") for m in d['models']])
    calls=table('Table 2. Budget per model call', ['GenAI call','Model','Input tokens','Output tokens','Total tokens','USD / call'],[(c['name'],c['model'],f"{c['input']:,}",f"{c['output']:,}",f"{c['input']+c['output']:,}",f"${c['usd']:.6f}") for c in d['calls']])
    by_id={c['id']:c for c in d['calls']}
    workflows=table('Table 3. From model calls to user actions', ['User action','Model sequence','Calls','USD / action'],[(w['name'],' → '.join(by_id[i]['name'] for i in w['composition']),len(w['composition']),f"${sum(by_id[i]['usd'] for i in w['composition']):.6f}") for w in d['workflows']])
    journeys=table('Table 4. Journey workloads from the report', ['Workload','Calls','Input tokens','Output tokens','USD / journey','USD / 1,000 journeys'],[(j['name']+'<small>'+f"{j['preferences']} preference request · {j['guidance']} guidance sentences · {j['localization']} landmark photo · {j['obstacle']} obstacle photo"+'</small>',j['calls'],f"{j['input']:,}",f"{j['output']:,}",f"${j['usd']:.6f}",f"${j['usd']*1000:.3f}") for j in d['journeys']])
    timing=table('Table 5. Timing evidence and its scope', ['Item','Time / statistic','Evidence type','What the record covers'],[(t['item'],t['value'],'<span class="budget-tag">'+t['kind']+'</span>',t['scope']) for t in d['timing']])
    targets=''.join(table('Table '+str(n)+'. '+title+' · acceptance targets',['Metric','Correctness criterion','Target'],[(x['metric'],x['criterion'],x['target']) for x in d[key]]) for n,key,title in [(6,'component_targets','Component quality'),(7,'workflow_targets','Complete workflows')])
    fields=''.join(f'<label for="budget-{key}">{label}<input id="budget-{key}" name="{key}" type="number" min="0" max="100" step="1" value="{value}" required></label>' for key,label,value in [('preferences','Preference requests',1),('guidance','Guidance sentences',13),('localization','Landmark photos',0),('obstacle','Obstacle photos',0)])
    return f'''<div class="method-page service-page"><div class="wrap">
<nav class="method-nav" aria-label="Technical methods"><a href="technology.html">Technology</a><a href="routing.html">Route planning</a><a href="localization.html">Visual localization</a><a href="service-budget.html" aria-current="page">API cost &amp; timing</a></nav>
<header class="method-header"><span class="method-kicker">ACCESSROUTE HK / SERVICE DATA</span><h1>API cost, timing and quality.</h1><p>See which actions use a model, how the report budgets each journey, and what the timing records establish.</p>
<div class="method-contents"><a href="#calculator">Cost calculator</a><a href="#prices">Model prices</a><a href="#calls">Call budgets</a><a href="#journeys">Journey budgets</a><a href="#timing">Response time</a><a href="#quality">Quality targets</a><a href="#sources">Sources &amp; downloads</a></div></header>
<div class="budget-summary"><article><span>Ordinary journey budget</span><strong>$0.020640</strong><small>1 preference request + 13 guidance sentences</small></article><article><span>One landmark photo budget</span><strong>$0.006032</strong><small>Visual observation + evidence matching</small></article><article><span>Text connectivity sample</span><strong>≈ 3.4 s</strong><small>One successful generic text request · 4 Oct 2026</small></article></div>
<p class="budget-context">Cost tables use the report’s price snapshot from <b>11 October 2026</b> and explicit token budgets. Actual charges follow billed usage and the service provider’s rates.</p>
<section class="budget-section budget-calculator" id="calculator"><span class="method-kicker">TRY THE WORKLOAD</span><h2>What would this journey cost?</h2><p>Change how often each action happens. A photo action includes both observation and matching; one guidance sentence uses one text call.</p>
<form id="budget-form"><fieldset><legend>Choose a report workload</legend><div class="budget-presets"><button type="button" data-budget-preset="0">Ordinary journey</button><button type="button" data-budget-preset="1">Add location assistance</button><button type="button" data-budget-preset="2">Both photo workflows</button></div></fieldset><div class="budget-fields">{fields}<label for="budget-volume">Number of journeys<input id="budget-volume" name="volume" type="number" min="1" max="1000000" step="1" value="1000" required></label></div></form>
<p id="budget-error" class="budget-error" role="alert" hidden>Use whole numbers from 0 to 100 for actions and 1 to 1,000,000 for journeys.</p>
<div id="budget-results" role="status" aria-live="polite" aria-atomic="true"><div class="budget-totals"><div><span>USD / journey</span><output id="cost-per-journey">$0.020640</output></div><div><span>Total USD · <span id="volume-label">1,000</span> journeys</span><output id="cost-total">$20.640</output></div><div><span>Model calls / journey</span><output id="cost-calls">14</output></div></div><p id="cost-tokens">7,050 input tokens + 1,090 output tokens per journey.</p></div>
<p class="budget-footnote">Model inference budget. Maps, hosting, storage and browser speech have separate service-cost categories. Page viewing, route search, confirmation and session synchronization add zero GenAI calls.</p><noscript><p>The tables below contain all three report workloads. Enable JavaScript to adjust the calculator.</p></noscript></section>
<section class="budget-section" id="prices"><h2>Prices turn tokens into charges.</h2><p>A token is a unit of model input or generated output. Input includes the instructions, context and image tokens. Output includes billable reasoning tokens when the selected mode produces them.</p>{prices}<p class="budget-footnote">Historical rates reproduced from report Table 4; vision input tier ≤ 32,000 tokens. T = Qwen3.8-Max, V = Qwen3-VL-Plus throughout the call table.</p><div class="budget-formula" role="math" aria-label="Charge equals input tokens times input price plus output tokens times output price, divided by one million">Charge (USD) = (input tokens × input price + output tokens × output price) / 1,000,000</div></section>
<section class="budget-section" id="calls"><h2>Each action has a call budget.</h2><p>Reading a photo and matching its evidence use different model calls. Local map retrieval and deterministic ranking sit between those calls.</p>{calls}{workflows}</section>
<section class="budget-section" id="journeys"><h2>A journey combines the actions.</h2><p>The report lists three workloads. Guidance counts include the sentences generated after route updates.</p>{journeys}</section>
<section class="budget-section" id="timing"><h2>Response time needs a defined scope.</h2><p>The records distinguish one observed response, a configured deadline, and the workflow statistics that still need measurement. p95 means 95% of measured requests finish within that time.</p>{timing}<div class="budget-timing-flow"><div><b>Text workflow</b><span>1 model call + local validation</span></div><div><b>Photo workflow</b><span>Vision → local retrieval → text matching → local ranking</span></div></div><p class="budget-footnote">The 3.4-second sample provides connectivity evidence. It does not supply navigation-workflow averages. Measure each complete workflow from request submission to usable result; record sample count, median, p95 and failures together.</p></section>
<section class="budget-section" id="quality"><h2>Quality has explicit acceptance targets.</h2><p>The report defines the following thresholds for evaluation. These percentages are acceptance targets; the tables do not contain measured accuracy results.</p><details><summary>Show component and workflow target tables</summary>{targets}</details></section>
<section class="budget-section" id="sources"><h2>Trace every number to its source.</h2><p>Costs and targets follow section 23 of the technical report. Timing comes from the dated live-integration note and the provider’s request configuration.</p><div class="budget-downloads"><a href="downloads/product-manual.pdf" target="_blank" rel="noopener">Technical report · section 23 ↗</a><a href="downloads/service-budget.json" download>Data snapshot · JSON ↓</a><a href="downloads/service-budget.csv" download>Budget tables · CSV ↓</a><a href="downloads/service-budget-source.txt" download>Report extract &amp; timing provenance ↓</a></div><ul class="source-files"><li><a href="https://github.com/XanderZhou2022/AccessRoute_small_demo/blob/7a8024d3706c3ebfaf46163e78be988c4c501ef4/docs/qa/qwen-live.md" target="_blank" rel="noopener">Live API integration record · 4 October 2026 ↗</a></li><li><a href="https://github.com/XanderZhou2022/AccessRoute_small_demo/blob/7a8024d3706c3ebfaf46163e78be988c4c501ef4/backend/providers/qwen.ts#L42" target="_blank" rel="noopener">Provider request timeout · source snapshot ↗</a></li><li>Price sources cited by the report: <a href="https://www.qwencloud.com/models/qwen3.8-max" target="_blank" rel="noopener">Qwen3.8-Max ↗</a><a href="https://www.qwencloud.com/models/qwen3-vl-plus" target="_blank" rel="noopener">Qwen3-VL-Plus ↗</a></li></ul></section>
</div></div>'''
